   "newText": "def transform(grid):
    """Connect all 2s to the longest row- or column-aligned marker line."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    rows, cols = {}, {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    # Select the most extended collinear pair as the network's spine.
    row_spines = [(max(cs) - min(cs), "row", r, min(cs), max(cs))
                  for r, cs in rows.items()]
    col_spines = [(max(rs) - min(rs), "col", c, min(rs), max(rs))
                  for c, rs in cols.items()]
    _, orient, fixed, lo, hi = max(row_spines + col_spines)
    if orient == "row":
        for c in range(lo + 1, hi):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r != fixed and lo <= c <= hi:
                step = 1 if fixed > r else -1
                for rr in range(r + step, fixed, step):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
